/** Encode a generated CSIL record to canonical CBOR bytes. */
fun <T> encode(value: T): ByteArray = CsilCbor.encode(csilToCborValue(value))

private fun csilToCborValue(value: Any?): CborValue = when (value) {
    null -> CborValue.CNull
    is IdentityRef -> value.toCborValue()
    is User -> value.toCborValue()
    is PersonSummary -> value.toCborValue()
    is Calendar -> value.toCborValue()
    is CreateCalendarRequest -> value.toCborValue()
    is UpdateCalendarRequest -> value.toCborValue()
    is SubscribeCalendarRequest -> value.toCborValue()
    is SetFeedRequest -> value.toCborValue()
    is CalendarList -> value.toCborValue()
    is Share -> value.toCborValue()
    is ShareList -> value.toCborValue()
    is Delegation -> value.toCborValue()
    is DelegationList -> value.toCborValue()
    is AssumePrincipalRequest -> value.toCborValue()
    is Recurrence -> value.toCborValue()
    is Attendee -> value.toCborValue()
    is Reminder -> value.toCborValue()
    is Event -> value.toCborValue()
    is Occurrence -> value.toCborValue()
    is ListEventsRequest -> value.toCborValue()
    is OccurrenceList -> value.toCborValue()
    is UpdateEventRequest -> value.toCborValue()
    is DeleteEventRequest -> value.toCborValue()
    is MoveEventRequest -> value.toCborValue()
    is RespondRequest -> value.toCborValue()
    is SearchEventsRequest -> value.toCborValue()
    is EventList -> value.toCborValue()
    is BusyInterval -> value.toCborValue()
    is FreeBusyRequest -> value.toCborValue()
    is PersonFreeBusy -> value.toCborValue()
    is FreeBusyResponse -> value.toCborValue()
    is ImportIcsRequest -> value.toCborValue()
    is ImportResult -> value.toCborValue()
    is ExportCalendarRequest -> value.toCborValue()
    is ExportEventRequest -> value.toCborValue()
    is IcsDocument -> value.toCborValue()
    is AuditEntry -> value.toCborValue()
    is AuditQuery -> value.toCborValue()
    is AuditList -> value.toCborValue()
    is CompleteRequest -> value.toCborValue()
    is LoginResponse -> value.toCborValue()
    is MeResponse -> value.toCborValue()
    is ExchangeActAsCredentialRequest -> value.toCborValue()
    is ScopeSetRequest -> value.toCborValue()
    is ScopeSetResponse -> value.toCborValue()
    is DevUser -> value.toCborValue()
    is DevUsersResponse -> value.toCborValue()
    is DevLoginRequest -> value.toCborValue()
    is LookupPersonRequest -> value.toCborValue()
    is UpdateProfileRequest -> value.toCborValue()
    is EmptyRequest -> value.toCborValue()
    is EmptyResponse -> value.toCborValue()
    is ServiceError -> value.toCborValue()
    else -> throw CborError("no CSIL CBOR codec for ${value::class}")
}

/** Decode canonical CBOR bytes into a generated CSIL record of type [T]. */
inline fun <reified T> decode(bytes: ByteArray): T =
    csilFromCborValue(T::class, CsilCbor.decode(bytes)) as T

fun csilFromCborValue(type: kotlin.reflect.KClass<*>, cbor: CborValue): Any = when (type) {
    IdentityRef::class -> identityRefFromCborValue(cbor)
    User::class -> userFromCborValue(cbor)
    PersonSummary::class -> personSummaryFromCborValue(cbor)
    Calendar::class -> calendarFromCborValue(cbor)
    CreateCalendarRequest::class -> createCalendarRequestFromCborValue(cbor)
    UpdateCalendarRequest::class -> updateCalendarRequestFromCborValue(cbor)
    SubscribeCalendarRequest::class -> subscribeCalendarRequestFromCborValue(cbor)
    SetFeedRequest::class -> setFeedRequestFromCborValue(cbor)
    CalendarList::class -> calendarListFromCborValue(cbor)
    Share::class -> shareFromCborValue(cbor)
    ShareList::class -> shareListFromCborValue(cbor)
    Delegation::class -> delegationFromCborValue(cbor)
    DelegationList::class -> delegationListFromCborValue(cbor)
    AssumePrincipalRequest::class -> assumePrincipalRequestFromCborValue(cbor)
    Recurrence::class -> recurrenceFromCborValue(cbor)
    Attendee::class -> attendeeFromCborValue(cbor)
    Reminder::class -> reminderFromCborValue(cbor)
    Event::class -> eventFromCborValue(cbor)
    Occurrence::class -> occurrenceFromCborValue(cbor)
    ListEventsRequest::class -> listEventsRequestFromCborValue(cbor)
    OccurrenceList::class -> occurrenceListFromCborValue(cbor)
    UpdateEventRequest::class -> updateEventRequestFromCborValue(cbor)
    DeleteEventRequest::class -> deleteEventRequestFromCborValue(cbor)
    MoveEventRequest::class -> moveEventRequestFromCborValue(cbor)
    RespondRequest::class -> respondRequestFromCborValue(cbor)
    SearchEventsRequest::class -> searchEventsRequestFromCborValue(cbor)
    EventList::class -> eventListFromCborValue(cbor)
    BusyInterval::class -> busyIntervalFromCborValue(cbor)
    FreeBusyRequest::class -> freeBusyRequestFromCborValue(cbor)
    PersonFreeBusy::class -> personFreeBusyFromCborValue(cbor)
    FreeBusyResponse::class -> freeBusyResponseFromCborValue(cbor)
    ImportIcsRequest::class -> importIcsRequestFromCborValue(cbor)
    ImportResult::class -> importResultFromCborValue(cbor)
    ExportCalendarRequest::class -> exportCalendarRequestFromCborValue(cbor)
    ExportEventRequest::class -> exportEventRequestFromCborValue(cbor)
    IcsDocument::class -> icsDocumentFromCborValue(cbor)
    AuditEntry::class -> auditEntryFromCborValue(cbor)
    AuditQuery::class -> auditQueryFromCborValue(cbor)
    AuditList::class -> auditListFromCborValue(cbor)
    CompleteRequest::class -> completeRequestFromCborValue(cbor)
    LoginResponse::class -> loginResponseFromCborValue(cbor)
    MeResponse::class -> meResponseFromCborValue(cbor)
    ExchangeActAsCredentialRequest::class -> exchangeActAsCredentialRequestFromCborValue(cbor)
    ScopeSetRequest::class -> scopeSetRequestFromCborValue(cbor)
    ScopeSetResponse::class -> scopeSetResponseFromCborValue(cbor)
    DevUser::class -> devUserFromCborValue(cbor)
    DevUsersResponse::class -> devUsersResponseFromCborValue(cbor)
    DevLoginRequest::class -> devLoginRequestFromCborValue(cbor)
    LookupPersonRequest::class -> lookupPersonRequestFromCborValue(cbor)
    UpdateProfileRequest::class -> updateProfileRequestFromCborValue(cbor)
    EmptyRequest::class -> emptyRequestFromCborValue(cbor)
    EmptyResponse::class -> emptyResponseFromCborValue(cbor)
    ServiceError::class -> serviceErrorFromCborValue(cbor)
    else -> throw CborError("no CSIL CBOR codec for $type")
}
